DROP VIEW IF EXISTS `vdholiday_event`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vdholiday_event` AS select substr(`dl`.`date_leave_start`,4,2) AS `month`,substr(`dl`.`date_leave_start`,1,2) AS `day`,substr(`dl`.`date_leave_start`,7,4) AS `year`,`dl`.`id` AS `id`,`dl`.`doc_year` AS `doc_year`,`dl`.`doc_id` AS `doc_id`,`dl`.`doc_date` AS `doc_date`,`dl`.`leave_type_id` AS `leave_type_id`,`dl`.`emp_id` AS `emp_id`,`dl`.`date_leave_start` AS `date_leave_start`,`dl`.`date_leave_to` AS `date_leave_to`,`dl`.`time_leave_start` AS `time_leave_start`,`dl`.`time_leave_to` AS `time_leave_to`,`dl`.`approve_1_id` AS `approve_1_id`,`dl`.`approve_1_status` AS `approve_1_status`,`dl`.`approve_2_id` AS `approve_2_id`,`dl`.`approve_2_status` AS `approve_2_status`,`dl`.`remark` AS `remark`,`dl`.`status` AS `status`,`lt`.`leave_type_detail` AS `leave_type_detail`,`ms`.`status_doc_desc` AS `status_doc_desc`,`dl`.`dept_id` AS `dept_id`,`em`.`f_name` AS `f_name`,`em`.`l_name` AS `l_name`,`em`.`department_id` AS `department_id` from (((`dholiday_event` `dl` left join `memployee` `em` on((`em`.`emp_id` = `dl`.`emp_id`))) left join `mleave_type` `lt` on((`lt`.`leave_type_id` = `dl`.`leave_type_id`))) left join `mstatus` `ms` on(((`ms`.`status_doctype` = 'LEAVE') and (`ms`.`status_doc_id` = `dl`.`status`))));

